"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[7514],{6642(e){e.exports=JSON.parse('{"tag":{"label":"Pruning","permalink":"/concepts/tags/pruning","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"state-space-search-and-optimization/exercises","title":"Exercises: Backtracking and Branch and Bound","description":"These exercises review the four lessons of the chapter. They are different from the seminar activities (paths, Hamiltonian cycles and the traveling salesman) and from the lab problems, which are left for those sessions. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/state-space-search-and-optimization/exercises"},{"id":"state-space-search-and-optimization/proofs","title":"Proofs: Backtracking and Branch and Bound","description":"Backtracking and branch and bound are exact methods: they promise to find every solution, or the optimal one. That promise depends on the pruning being safe, that is, never discarding a branch that contains what we are looking for. This page proves when that is the case, and proves the specific facts used in the examples.","permalink":"/concepts/state-space-search-and-optimization/proofs"}],"unlisted":false}}')}}]);